const config = {
  "previewFeatures": [],
  "clientVersion": "7.2.0",
  "engineVersion": "0c8ef2ce45c83248ab3df073180d5eda9e8be7a3",
  "activeProvider": "postgresql",
  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Looking for ways to speed up your queries, or scale easily with your serverless or edge functions?\n// Try Prisma Accelerate: https://pris.ly/cli/accelerate-init\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum AuthRole {\n  USER\n  ADMIN\n  SUPER_ADMIN\n  SUPPORT\n}\n\nenum DocumentType {\n  LOGO\n  BANNER\n  IMAGE\n  VIDEO\n  AUDIO\n  PDF\n  DOCUMENT\n  OTHER\n}\n\nenum CrawlType {\n  HTML\n  API\n  GRAPHQL\n  PLAYWRIGHT\n  SITEMAP\n  HYBRID\n}\n\nenum PaginationType {\n  NONE\n  PAGE_NUMBER\n  OFFSET\n  CURSOR\n  INFINITE_SCROLL\n  LOAD_MORE\n  UNKNOWN\n}\n\n// Added BROKEN to support spec section 19 (Broken Scraper Detection).\nenum ScraperStatus {\n  ACTIVE\n  INACTIVE\n  DEPRECATED\n  TESTING\n  BROKEN\n}\n\n// Rolled-up health rating shown on the dashboard (spec section 18).\nenum ScraperHealth {\n  EXCELLENT\n  GOOD\n  WARNING\n  CRITICAL\n  BROKEN\n}\n\n// Status for production scraping executions (Playwright runs against a live Scraper).\nenum CrawlRunStatus {\n  QUEUED\n  RUNNING\n  SUCCESS\n  PARTIAL_SUCCESS\n  FAILED\n  CANCELLED\n}\n\n// Debugging depth for the diagnostics subsystem (docs/playwright-debug.md). Determined per\n// Scraper, before browser context creation -- Playwright tracing cannot be enabled retroactively.\nenum DiagnosticsMode {\n  PRODUCTION // logs/timings/errors/metrics only, no tracing -- the default, smallest overhead\n  TRACE // Playwright trace (screenshots, DOM snapshots, console, actions, timings)\n  FULL_DEBUG // trace + video + HTML snapshot + network HAR -- development / hard production bugs\n}\n\nenum DiagnosticsArtifactKind {\n  TRACE\n  SCREENSHOT\n  HTML_SNAPSHOT\n  CONSOLE_LOG\n  NETWORK_HAR\n  VIDEO\n}\n\nenum ContentLanguage {\n  EL\n  EN\n  DE\n  FR\n  IT\n  RU\n}\n\nenum ContentType {\n  TITLE\n  DESCRIPTION\n}\n\nenum TitleProductionStrategy {\n  ORIGINAL\n  TRANSLATE\n  AI\n}\n\nenum DescriptionProductionStrategy {\n  ORIGINAL\n  TRANSLATE\n}\n\nenum AiBatchRunKind {\n  TITLE_FAMILY\n}\n\nenum AiBatchRunStatus {\n  SUBMITTED\n  IN_PROGRESS\n  COMPLETED\n  FAILED\n  CANCELLED\n}\n\n// Separate from CrawlRunStatus: an AI generation/self-heal session has different\n// terminal states than a production crawl (e.g. AWAITING_REVIEW has no crawl equivalent).\nenum GenerationRunStatus {\n  QUEUED\n  RUNNING\n  AWAITING_REVIEW // config produced, not yet promoted to a ScraperVersion\n  SUCCESS\n  FAILED\n  CANCELLED\n}\n\n// Why a ScraperGenerationRun was started.\nenum GenerationTrigger {\n  MANUAL // user requested a scraper for a new/existing agency\n  SELF_HEAL // triggered automatically after a CrawlRun failure\n  SCHEDULED // periodic re-generation/health check\n}\n\n// A single computer-use action returned by the model during a generation run.\nenum ComputerActionType {\n  CLICK\n  DOUBLE_CLICK\n  TYPE\n  SCROLL\n  SCROLL_UP\n  SCROLL_DOWN\n  NAVIGATE\n  GO_BACK\n  CLOSE_TAB\n  WAIT\n  KEYPRESS\n  SCREENSHOT\n  DRAG\n  DONE\n}\n\nenum JobStatus {\n  WAITING\n  ACTIVE\n  COMPLETED\n  FAILED\n  DELAYED\n  PAUSED\n  STALLED\n}\n\nenum PropertyStatus {\n  ACTIVE\n  INACTIVE\n  REMOVED\n  SOLD\n  RENTED\n  UNKNOWN\n}\n\nenum ListingType {\n  SALE\n  RENT\n  SHORT_TERM_RENT\n  UNKNOWN\n}\n\nenum PropertyType {\n  APARTMENT\n  HOUSE\n  VILLA\n  MAISONETTE\n  STUDIO\n  LAND\n  COMMERCIAL\n  OFFICE\n  WAREHOUSE\n  PARKING\n  OTHER\n  UNKNOWN\n}\n\nenum IntegrationType {\n  ESTATEWEB\n  OPENAI\n  ANTHROPIC\n  GEMINI\n  DEEPSEEK\n  DEWATERMARK\n  GOOGLE_TRANSLATE\n  AZURE\n}\n\n// New: unified cost logging -- what kind of billable operation incurred the cost.\nenum CostOperationType {\n  NORMALIZATION\n  TITLE_GENERATION\n  TRANSLATION\n  DEWATERMARK\n  OTHER\n}\n\nenum AuthType {\n  EMAIL_PASSWORD\n  USERNAME_PASSWORD\n  BEARER_TOKEN\n  API_KEY\n  OAUTH\n}\n\nenum CmsSyncStatus {\n  PENDING\n  SUCCESS\n  FAILED\n  RETRYING\n}\n\n// New: spec section 14 Property History -- every detectable change to a Property over time.\nenum PropertyHistoryEventType {\n  CREATED\n  UPDATED\n  PRICE_CHANGED\n  IMAGE_ADDED\n  IMAGE_REMOVED\n  STATUS_CHANGED\n  REMOVED\n  REAPPEARED\n}\n\n// New: spec section 20 Notifications.\nenum NotificationType {\n  BROKEN_SCRAPER\n  CMS_SYNC_FAILURE\n  CMS_SYNC_SUCCESS\n  PROPERTY_REMOVAL_SPIKE\n  LARGE_CRAWL_FAILURE\n  QUEUE_FAILURE\n  WEBSITE_UNAVAILABLE\n  ESTATEWEB_NETWORK_ERROR\n  ESTATEWEB_REQUEST_TIMEOUT\n  ESTATEWEB_UNAUTHORIZED\n  ESTATEWEB_SESSION_EXPIRED\n  ESTATEWEB_API_ERROR\n  ESTATEWEB_NOT_FOUND\n  ESTATEWEB_RATE_LIMITED\n  ESTATEWEB_INVALID_RESPONSE\n  ESTATEWEB_MISSING_PROPERTY_ID\n  ESTATEWEB_VALIDATION_FAILED\n  ESTATEWEB_LOGIN_FAILED\n  ESTATEWEB_MISSING_CSRF\n  ESTATEWEB_MISSING_SESSION_COOKIE\n  ESTATEWEB_LOGIN_REDIRECT_FAILED\n  ESTATEWEB_MISSING_CREDENTIALS\n  ESTATEWEB_INTEGRATION_INACTIVE\n  ESTATEWEB_INTEGRATION_NOT_FOUND\n  ESTATEWEB_MISSING_TOKEN\n  ESTATEWEB_INVALID_JSON\n  ESTATEWEB_SERVER_ERROR\n  ESTATEWEB_EMPTY_IMAGE\n  ESTATEWEB_INVALID_PROPERTY_ID\n  ESTATEWEB_LINK_NOT_FOUND\n  ESTATEWEB_SESSION_PERSIST_FAILED\n  AI_NORMALIZATION_FAILURE\n}\n\nenum NotificationSeverity {\n  INFO\n  WARNING\n  CRITICAL\n}\n\n// Who created a ScraperVersion.\nenum ScraperVersionCreatedBy {\n  AI\n  USER\n}\n\n// ---------------------------------------------------------------\n// USERS & CMS\n// ---------------------------------------------------------------\n\n/// App users. Can track agencies and save properties.\nmodel User {\n  id       String  @id @default(uuid())\n  email    String  @unique\n  phone    String? @unique\n  password String\n\n  role       AuthRole\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  tracked_agencies          UserTrackedAgency[]\n  saved_properties          UserProperty[]\n  user_integrations         UserIntegration[]\n  user_integration_settings UserIntegrationSettings[]\n  integration_properties    IntegrationProperty[]\n  cost_logs                 CostLog[]\n\n  @@index([email])\n  @@index([phone])\n  @@map(\"users\")\n}\n\n/// Destination Integration instance that normalized Property data gets synced to and ai models are integrated with.\nmodel IntegrationTarget {\n  id               String          @id @default(uuid())\n  integration_type IntegrationType\n  auth_type        AuthType\n  base_url         String?\n  allow_multiple   Boolean         @default(false)\n  is_visible       Boolean         @default(true) // whether the integration is visible to the user (always visible for admin and supper admin)\n  is_enabled       Boolean         @default(true) // when false, users can view but not connect or modify on the Integrations page\n  created_at       DateTime        @default(now())\n  updated_at       DateTime        @updatedAt\n\n  user_integrations         UserIntegration[]\n  user_integration_settings UserIntegrationSettings[]\n\n  @@map(\"integration_targets\")\n}\n\n/// Shared configuration for a user's connection to one IntegrationTarget, independent of which\n/// UserIntegration (account) is used. Exists so that integration-wide settings (e.g. EstateWeb\n/// sync behavior) are edited once per (user, integration_target) instead of duplicated across\n/// every connected account allowed by IntegrationTarget.allow_multiple.\nmodel UserIntegrationSettings {\n  id                    String   @id @default(uuid())\n  integration_target_id String\n  user_id               String\n  settings              Json?\n  created_at            DateTime @default(now())\n  updated_at            DateTime @updatedAt\n\n  user                   User                  @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  integration_target     IntegrationTarget     @relation(fields: [integration_target_id], references: [id], onDelete: Cascade)\n  accounts               UserIntegration[]\n  integration_properties IntegrationProperty[]\n\n  @@unique([user_id, integration_target_id])\n  @@map(\"user_integration_settings\")\n}\n\nmodel UserIntegration {\n  id                           String   @id @default(uuid())\n  integration_target_id        String\n  user_id                      String\n  user_integration_settings_id String\n  api_key_secret               String?\n  webhook_key                  String?\n  email                        String?\n  username                     String?\n  password                     String?\n  config                       Json?\n  is_active                    Boolean  @default(true)\n  is_default                   Boolean  @default(false)\n  created_at                   DateTime @default(now())\n  updated_at                   DateTime @updatedAt\n\n  sync_runs           CmsSyncRun[]\n  tracked_agency_link UserTrackedAgencyIntegrationLink?\n  user                User                              @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  integration_target  IntegrationTarget                 @relation(fields: [integration_target_id], references: [id], onDelete: Cascade)\n  settings            UserIntegrationSettings           @relation(fields: [user_integration_settings_id], references: [id], onDelete: Cascade)\n\n  @@map(\"user_integrations\")\n}\n\n// ---------------------------------------------------------------\n// SOURCE AGENCIES (scrape targets)\n// ---------------------------------------------------------------\n\n/// A target website (real-estate agency) to be scraped. Root of the whole pipeline:\n/// SourceAgency -> ScraperGenerationRun (AI builds a scraper) -> Scraper -> CrawlRun (production run)\n/// -> SourceProperty -> Property.\nmodel SourceAgency {\n  id                 String          @id @default(uuid())\n  name               String\n  base_url           String          @unique\n  country            String?\n  city               String?\n  content_language   ContentLanguage @default(EL)\n  is_visible         Boolean         @default(false) // not displayed to the user, only to the admin\n  is_enabled         Boolean         @default(false) // appears to the user for the UserTrackedAgency but cannot be activated, but not to the admin\n  crawl_interval     String          @default(\"0 */6 * * *\")\n  notes              String?\n  last_success_at    DateTime?\n  last_failure_at    DateTime?\n  last_error_message String?\n  metadata           Json?\n  created_at         DateTime        @default(now())\n  updated_at         DateTime        @updatedAt\n\n  scrapers                Scraper[]\n  user_tracked_agencies   UserTrackedAgency[]\n  scraper_generation_runs ScraperGenerationRun[]\n  crawl_runs              CrawlRun[]\n  source_properties       SourceProperty[]\n  notifications           Notification[]\n\n  @@index([is_visible])\n  @@index([is_enabled])\n  @@map(\"source_agencies\")\n}\n\n/// Which SourceAgencies a user follows/monitors, and which kinds of change notify them.\nmodel UserTrackedAgency {\n  id                         String   @id @default(uuid())\n  user_id                    String\n  source_agency_id           String\n  enabled                    Boolean  @default(true)\n  concurrent_insertions      Int      @default(1) // the number of properties to insert concurrently to the EstateWeb integration\n  insertion_interval_seconds Int      @default(300) // delay between concurrent insertion chunks to the CMS integration\n  max_properties             Int? // max listings allowed in the linked CRM; null = unlimited\n  text_truncate_pieces       String[] @default([])\n  track_new_listings         Boolean  @default(true)\n  track_removed_listings     Boolean  @default(true)\n  track_updated_listings     Boolean  @default(true)\n  auto_update_to_crm         Boolean  @default(true) // when false, CRM updates are pushed manually from Properties\n  use_ai_batching            Boolean  @default(false)\n  remove_watermark           Boolean  @default(false)\n  watermark_image_count      Int      @default(10)\n  watermark_manual_selection Boolean  @default(false)\n  created_at                 DateTime @default(now())\n  updated_at                 DateTime @updatedAt\n\n  user                      User                              @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  source_agency             SourceAgency                      @relation(fields: [source_agency_id], references: [id], onDelete: Cascade)\n  crawl_runs                CrawlRun[]\n  integration_link          UserTrackedAgencyIntegrationLink?\n  content_publishing_config ContentPublishingConfig?\n  cost_logs                 CostLog[]\n\n  @@unique([user_id, source_agency_id])\n  @@index([user_id])\n  @@index([source_agency_id])\n  @@map(\"user_tracked_agencies\")\n}\n\nmodel UserTrackedAgencyIntegrationLink {\n  id                     String   @id @default(uuid())\n  user_tracked_agency_id String   @unique\n  user_integration_id    String   @unique\n  integration_client_id  Int?\n  created_at             DateTime @default(now())\n  updated_at             DateTime @updatedAt\n\n  user_tracked_agency UserTrackedAgency @relation(fields: [user_tracked_agency_id], references: [id], onDelete: Cascade)\n  user_integration    UserIntegration   @relation(fields: [user_integration_id], references: [id], onDelete: Cascade)\n\n  @@map(\"user_tracked_agency_integration_links\")\n}\n\n// ---------------------------------------------------------------\n// AI GENERATION LAYER (computer-use loop)\n// ---------------------------------------------------------------\n\n/// A scraper definition for one agency. Holds NO config directly -- config always lives on the\n/// active ScraperVersion (see `active_version`). This keeps a single source of truth instead of\n/// letting Scraper.config and ScraperVersion.config drift out of sync.\nmodel Scraper {\n  id                   String          @id @default(uuid())\n  source_agency_id     String\n  name                 String\n  active_version_id    String?         @unique // FK to the ScraperVersion currently in use\n  version_count        Int             @default(0) // convenience counter, incremented on new versions\n  status               ScraperStatus   @default(TESTING)\n  self_healing_enabled Boolean         @default(true) // whether self-heal is allowed to auto-apply fixes\n  diagnostics_mode     DiagnosticsMode @default(PRODUCTION) // debugging depth for this scraper's crawl runs\n  health               ScraperHealth   @default(GOOD) // cached rollup, recomputed by a background job (spec section 18)\n  success_rate         Decimal?        @db.Decimal(5, 2) // cached % over trailing window\n  avg_runtime_ms       Int? // cached average CrawlRun duration\n  consecutive_failures Int             @default(0) // reset to 0 on any SUCCESS CrawlRun\n  normalize_limit      Int? // max SourceProperties to AI-normalize per crawl; null = unlimited\n  last_success_at      DateTime?\n  last_failure_at      DateTime?\n  created_at           DateTime        @default(now())\n  updated_at           DateTime        @updatedAt\n\n  source_agency  SourceAgency    @relation(fields: [source_agency_id], references: [id], onDelete: Cascade)\n  active_version ScraperVersion? @relation(\"ActiveVersion\", fields: [active_version_id], references: [id], onDelete: SetNull)\n\n  crawl_runs              CrawlRun[]\n  versions                ScraperVersion[]        @relation(\"ScraperVersions\")\n  execution_traces        ScraperExecutionTrace[]\n  scraper_generation_runs ScraperGenerationRun[]\n  notifications           Notification[]\n  diagnostics_packages    DiagnosticsPackage[]\n\n  @@index([source_agency_id])\n  @@index([status])\n  @@index([health])\n  @@map(\"scrapers\")\n}\n\n/// One AI (or human) session that produces or fixes a scraper config. This is the row that\n/// owns a computer-use loop: it's created, the loop runs (see ComputerUseStep), and it ends\n/// with either a promoted ScraperVersion or a failure.\nmodel ScraperGenerationRun {\n  id                  String              @id @default(uuid())\n  source_agency_id    String\n  scraper_id          String? // set when this run is fixing/updating an existing Scraper (self-heal or manual re-gen)\n  trigger             GenerationTrigger   @default(MANUAL)\n  status              GenerationRunStatus @default(QUEUED)\n  prompt              String? // goal/instructions given to the model\n  staged_config       Json? // draft config produced by the model, pending review/promotion\n  produced_version_id String?             @unique // set once staged_config is approved and copied into a ScraperVersion\n  error_message       String?\n  started_at          DateTime?\n  finished_at         DateTime?\n  duration_ms         Int?\n  created_at          DateTime            @default(now())\n  updated_at          DateTime            @updatedAt\n\n  source_agency    SourceAgency    @relation(fields: [source_agency_id], references: [id], onDelete: Cascade)\n  scraper          Scraper?        @relation(fields: [scraper_id], references: [id], onDelete: SetNull)\n  produced_version ScraperVersion? @relation(\"ProducedVersion\", fields: [produced_version_id], references: [id], onDelete: SetNull)\n\n  steps ComputerUseStep[]\n\n  @@index([source_agency_id])\n  @@index([scraper_id])\n  @@index([status])\n  @@map(\"scraper_generation_runs\")\n}\n\n/// A single action in the computer-use loop: model receives a screenshot, returns an action\n/// (click/type/scroll/...), Playwright executes it, a new screenshot is captured. Storing every\n/// step lets you replay a session, debug why the AI navigated somewhere wrong, and show the\n/// user an audit trail of how a scraper config was derived.\nmodel ComputerUseStep {\n  id                        String             @id @default(uuid())\n  scraper_generation_run_id String\n  step_index                Int // ordering within the run, starting at 0\n  action_type               ComputerActionType\n  action_payload            Json // raw action from the model, e.g. {\"x\":320,\"y\":540} or {\"text\":\"...\"}\n  screenshot_before_id      String?\n  screenshot_after_id       String?\n  model_reasoning           String? // optional chain-of-thought / rationale text returned by the model\n  created_at                DateTime           @default(now())\n\n  scraper_generation_run ScraperGenerationRun @relation(fields: [scraper_generation_run_id], references: [id], onDelete: Cascade)\n  screenshot_before      Document?            @relation(\"ComputerUseStepScreenshotBefore\", fields: [screenshot_before_id], references: [id], onDelete: SetNull)\n  screenshot_after       Document?            @relation(\"ComputerUseStepScreenshotAfter\", fields: [screenshot_after_id], references: [id], onDelete: SetNull)\n\n  @@index([scraper_generation_run_id])\n  @@index([scraper_generation_run_id, step_index])\n  @@index([screenshot_before_id])\n  @@index([screenshot_after_id])\n  @@map(\"computer_use_steps\")\n}\n\n/// Immutable, versioned scraper config. This is the single source of truth for \"what a scraper\n/// does\" -- Scraper.active_version_id points here. New versions are created by generation runs\n/// (AI) or manual edits (human review), enabling rollback and full history / self-healing.\nmodel ScraperVersion {\n  id         String                  @id @default(uuid())\n  scraper_id String\n  version    Int\n  config     Json // full scraper definition: start_url, listing_selector, fields, pagination, etc.\n  created_by ScraperVersionCreatedBy\n  notes      String? // e.g. reason for the fix, summary of what changed from prior version\n  created_at DateTime                @default(now())\n  updated_at DateTime                @updatedAt\n\n  scraper Scraper @relation(\"ScraperVersions\", fields: [scraper_id], references: [id], onDelete: Cascade)\n\n  // Back-relations used only to let other models point at \"the\" active/produced version.\n  active_for_scraper Scraper?              @relation(\"ActiveVersion\")\n  produced_by_run    ScraperGenerationRun? @relation(\"ProducedVersion\")\n\n  @@unique([scraper_id, version])\n  @@map(\"scraper_versions\")\n}\n\n/// Step-by-step log of a PRODUCTION Playwright execution (not the AI's exploratory computer-use\n/// loop -- see ComputerUseStep for that). Used to detect broken selectors / navigation failures\n/// and feed them into a self-heal ScraperGenerationRun.\nmodel ScraperExecutionTrace {\n  id            String   @id @default(uuid())\n  scraper_id    String\n  crawl_run_id  String?\n  steps         Json // Playwright step-by-step execution log\n  success       Boolean\n  error_summary String?\n  created_at    DateTime @default(now())\n  updated_at    DateTime @updatedAt\n\n  scraper   Scraper   @relation(fields: [scraper_id], references: [id], onDelete: Cascade)\n  crawl_run CrawlRun? @relation(fields: [crawl_run_id], references: [id], onDelete: SetNull)\n\n  @@index([scraper_id])\n  @@map(\"scraper_execution_traces\")\n}\n\n// ---------------------------------------------------------------\n// PRODUCTION EXECUTION LAYER\n// ---------------------------------------------------------------\n\n/// One production scraping execution of a Scraper against its SourceAgency. This is the\n/// Playwright run that uses the config from Scraper.active_version -- no AI involved in the\n/// crawl itself, unless normalization (Feature 06) or a failure triggers self-heal.\nmodel CrawlRun {\n  id                           String         @id @default(uuid())\n  source_agency_id             String\n  scraper_id                   String?\n  user_tracked_agency_id       String?\n  status                       CrawlRunStatus @default(QUEUED)\n  started_at                   DateTime?\n  finished_at                  DateTime?\n  duration_ms                  Int?\n  total_found                  Int            @default(0) // all items seen in this scrape (dedup'd within the run)\n  total_new_listings           Int            @default(0) // of total_found, how many were brand-new SourceProperty rows\n  total_refreshed_listings     Int            @default(0) // of total_found, how many were already-known SourceProperty rows re-seen\n  // total_created/updated/removed/linked/failed below are rolled up from cms_sync_runs (sum across\n  // every user's CmsSyncRun for this run) -- NOT the raw scrape diff above. Stays 0 until the\n  // EstateWeb sync writes results. See CrawlRunsService.recalculateCmsSyncTotals.\n  total_created                Int            @default(0)\n  total_updated                Int            @default(0)\n  total_removed                Int            @default(0)\n  total_linked                 Int            @default(0)\n  total_failed                 Int            @default(0)\n  error_message                String?\n  metadata                     Json?\n  ai_model                     String?\n  ai_input_tokens              Int?\n  ai_output_tokens             Int?\n  ai_input_cost                Decimal?       @db.Decimal(12, 6)\n  ai_output_cost               Decimal?       @db.Decimal(12, 6)\n  ai_total_cost                Decimal?       @db.Decimal(12, 6)\n  ai_average_cost_per_property Decimal?       @db.Decimal(12, 8)\n  created_at                   DateTime       @default(now())\n  updated_at                   DateTime       @updatedAt\n\n  source_agency       SourceAgency            @relation(fields: [source_agency_id], references: [id], onDelete: Cascade)\n  user_tracked_agency UserTrackedAgency?      @relation(fields: [user_tracked_agency_id], references: [id], onDelete: SetNull)\n  scraper             Scraper?                @relation(fields: [scraper_id], references: [id], onDelete: SetNull)\n  job_logs            JobLog[]\n  execution_traces    ScraperExecutionTrace[]\n  property_history    PropertyHistory[]\n  notifications       Notification[]\n  diagnostics_package DiagnosticsPackage?\n  cms_sync_runs       CmsSyncRun[]\n  ai_batch_runs       AiBatchRun[]\n  cost_logs           CostLog[]\n\n  @@index([source_agency_id])\n  @@index([scraper_id])\n  @@index([status])\n  @@index([created_at])\n  @@map(\"crawl_runs\")\n}\n\n/// Failure diagnostics package for a crawl run's main listing scrape. Created for any failed run\n/// regardless of Scraper.diagnostics_mode -- PRODUCTION gets screenshot/HTML/console log only,\n/// TRACE adds a Playwright trace.zip, FULL_DEBUG adds video + network HAR on top of that.\n/// Successful runs discard whatever was collected without persisting anything (see\n/// DiagnosticsCaptureService). Never created for watchdog-killed runs (crawl-run-watchdog.cron.ts)\n/// since there's no live page left to capture from once the worker process itself has died.\nmodel DiagnosticsPackage {\n  id                 String          @id @default(uuid())\n  crawl_run_id       String          @unique\n  scraper_id         String\n  mode               DiagnosticsMode\n  url                String\n  worker_id          String?\n  browser_version    String?\n  playwright_version String?\n  scraper_version    Int?\n  retry_number       Int?\n  started_at         DateTime\n  finished_at        DateTime\n  duration_ms        Int\n  failure_reason     String?\n  exception          String?\n  created_at         DateTime        @default(now())\n\n  crawl_run CrawlRun              @relation(fields: [crawl_run_id], references: [id], onDelete: Cascade)\n  scraper   Scraper               @relation(fields: [scraper_id], references: [id], onDelete: Cascade)\n  artifacts DiagnosticsArtifact[]\n\n  @@index([scraper_id])\n  @@map(\"diagnostics_packages\")\n}\n\n/// One stored blob (trace/screenshot/HTML/console/HAR/video) belonging to a DiagnosticsPackage,\n/// uploaded to GCS. Only `path` (the GCS object path) is persisted -- URLs are signed on demand\n/// at read time (see DiagnosticsService.findOne) since the bucket is private and a stored URL\n/// would go stale.\nmodel DiagnosticsArtifact {\n  id                     String                  @id @default(uuid())\n  diagnostics_package_id String\n  kind                   DiagnosticsArtifactKind\n  path                   String\n  content_type           String\n  size_bytes             Int\n  created_at             DateTime                @default(now())\n\n  diagnostics_package DiagnosticsPackage @relation(fields: [diagnostics_package_id], references: [id], onDelete: Cascade)\n\n  @@index([diagnostics_package_id])\n  @@map(\"diagnostics_artifacts\")\n}\n\n/// Generic queue/job execution log (e.g. BullMQ), optionally tied to a CrawlRun. Useful for\n/// ops/debugging independent of the scraping domain model.\nmodel JobLog {\n  id            String    @id @default(uuid())\n  queue_name    String\n  job_id        String?\n  job_name      String?\n  status        JobStatus\n  attempt       Int       @default(0)\n  max_attempts  Int?\n  crawl_run_id  String?\n  payload       Json?\n  result        Json?\n  error_message String?\n  stack_trace   String?\n  started_at    DateTime?\n  finished_at   DateTime?\n  duration_ms   Int?\n  created_at    DateTime  @default(now())\n  updated_at    DateTime  @updatedAt\n\n  crawl_run CrawlRun? @relation(fields: [crawl_run_id], references: [id], onDelete: SetNull)\n\n  @@index([queue_name])\n  @@index([job_id])\n  @@index([status])\n  @@index([crawl_run_id])\n  @@index([created_at])\n  @@map(\"job_logs\")\n}\n\n// New: dashboard section 20 -- persisted notifications, independent of any push/email channel.\nmodel Notification {\n  id               String               @id @default(uuid())\n  type             NotificationType\n  severity         NotificationSeverity @default(INFO)\n  title            String\n  message          String\n  source_agency_id String?\n  scraper_id       String?\n  crawl_run_id     String?\n  is_read          Boolean              @default(false)\n  created_at       DateTime             @default(now())\n\n  source_agency SourceAgency? @relation(fields: [source_agency_id], references: [id], onDelete: SetNull)\n  scraper       Scraper?      @relation(fields: [scraper_id], references: [id], onDelete: SetNull)\n  crawl_run     CrawlRun?     @relation(fields: [crawl_run_id], references: [id], onDelete: SetNull)\n\n  @@index([type])\n  @@index([severity])\n  @@index([is_read])\n  @@index([created_at])\n  @@map(\"notifications\")\n}\n\n// Per-type outbound alerting preference. A missing row means \"enabled at INFO\"\n// (the same as an explicit row with defaults) -- see NotificationSettingsService.\nmodel NotificationSetting {\n  id           String               @id @default(uuid())\n  type         NotificationType     @unique\n  enabled      Boolean              @default(true)\n  min_severity NotificationSeverity @default(INFO)\n  created_at   DateTime             @default(now())\n  updated_at   DateTime             @updatedAt\n\n  @@map(\"notification_settings\")\n}\n\n// New: spec section 15 -- one batch push of affected properties to a single\n// UserIntegration (e.g. one EstateWeb account). NOT one row per property: total_created/\n// total_updated/total_removed/total_linked/total_failed hold the outcome breakdown for the whole batch.\n// total_linked = reconciled to an existing CMS listing without a push (skipped_push).\n// crawl_run_id is set only when the batch was triggered by an actual scrape (CrawlRun.total_*\n// is then the sum of these across every user_integration for that run, see\n// CrawlRunsService.recalculateCmsSyncTotals); it is null for backfill/manual pushes that\n// aren't tied to a crawl. Retries update this same row in place (attempt/status/error_message/\n// response) rather than creating a new row per attempt.\nmodel CmsSyncRun {\n  id                  String        @id @default(uuid())\n  crawl_run_id        String?\n  user_integration_id String\n  status              CmsSyncStatus @default(PENDING)\n  attempt             Int           @default(0)\n  max_attempts        Int?\n  total_created       Int           @default(0)\n  total_updated       Int           @default(0)\n  total_removed       Int           @default(0)\n  total_linked        Int           @default(0)\n  total_failed        Int           @default(0)\n  payload             Json?\n  response            Json?\n  error_message       String?\n  started_at          DateTime?\n  finished_at         DateTime?\n  created_at          DateTime      @default(now())\n  updated_at          DateTime      @updatedAt\n\n  crawl_run        CrawlRun?       @relation(fields: [crawl_run_id], references: [id], onDelete: SetNull)\n  user_integration UserIntegration @relation(fields: [user_integration_id], references: [id], onDelete: Cascade)\n\n  @@unique([crawl_run_id, user_integration_id])\n  @@index([user_integration_id])\n  @@index([status])\n  @@index([created_at])\n  @@map(\"cms_sync_runs\")\n}\n\n// ---------------------------------------------------------------\n// OUTPUT LAYER\n// ---------------------------------------------------------------\n\n/// Raw listing as extracted from a single source website. Not yet normalized/deduplicated --\n/// that happens in Property. One SourceProperty per (agency, url).\nmodel SourceProperty {\n  id                String         @id @default(uuid())\n  source_agency_id  String\n  property_id       String // the property id from the agency url\n  internal_id       String? // the property public id from property description\n  source_url        String\n  canonical_url     String?\n  raw_title         String?\n  raw_description   String?\n  raw_price         String?\n  raw_location      String?\n  raw_property_type String?\n  raw_listing_type  String?\n  raw_sqm           String?\n  raw_bedrooms      String?\n  raw_bathrooms     String?\n  raw_data          Json?\n  raw_html_path     String? // GCS object path for the detail-page HTML snapshot\n  content_hash      String? // used for deduplication\n  first_seen_at     DateTime       @default(now())\n  last_seen_at      DateTime?\n  status            PropertyStatus @default(ACTIVE)\n  created_at        DateTime       @default(now())\n  updated_at        DateTime       @updatedAt\n\n  source_agency  SourceAgency         @relation(fields: [source_agency_id], references: [id], onDelete: Cascade)\n  property_links PropertySourceLink[]\n\n  @@unique([source_agency_id, source_url])\n  @@index([source_agency_id])\n  @@index([property_id])\n  @@index([internal_id])\n  @@index([content_hash])\n  @@index([status])\n  @@index([last_seen_at])\n  @@map(\"source_properties\")\n}\n\n/// Normalized, deduplicated property record -- the canonical entity synced to the CMS.\n/// May be backed by multiple SourceProperty rows (same listing found on multiple agencies).\nmodel Property {\n  id                    String         @id @default(uuid())\n  title                 String\n  description           String?\n  property_id           String // the property id from the agency url\n  internal_id           String? // the property public id from property description\n  listing_type          ListingType    @default(UNKNOWN)\n  property_type         PropertyType   @default(UNKNOWN)\n  status                PropertyStatus @default(ACTIVE)\n  price                 Decimal?       @db.Decimal(14, 2)\n  currency              String?        @default(\"EUR\")\n  city                  String?\n  district              String?\n  address               String?\n  postal_code           String?\n  country               String?\n  latitude              Decimal?       @db.Decimal(10, 7)\n  longitude             Decimal?       @db.Decimal(10, 7)\n  square_meters         Decimal?       @db.Decimal(10, 2)\n  bedrooms              Int?\n  bathrooms             Int?\n  floor                 String?\n  construction_year     Int?\n  renovation_year       Int?\n  features              Json?\n  images                Json?\n  normalized_data       Json?\n  estateweb_type_id     Int?\n  estateweb_location_id Int?\n  estateweb_scope_id    Int?\n  cms_fields            Json?\n  cms_metadata          Json?\n  video_url             String?\n  distance_airport      String?\n  distance_port         String?\n  distance_beach        String?\n  price_start           Decimal?       @db.Decimal(14, 2)\n  price_web             Decimal?       @db.Decimal(14, 2)\n  duplicate_group_id    String?\n  created_at            DateTime       @default(now())\n  updated_at            DateTime       @updatedAt\n\n  source_links         PropertySourceLink[]\n  user_property_copies UserProperty[]\n  history              PropertyHistory[] // spec section 14\n\n  @@index([listing_type])\n  @@index([property_type])\n  @@index([status])\n  @@index([city])\n  @@index([district])\n  @@index([price])\n  @@index([duplicate_group_id])\n  @@index([property_id])\n  @@index([internal_id])\n  @@map(\"properties\")\n}\n\n/// Mapping layer between normalized Property and the raw SourceProperty rows it was built from.\nmodel PropertySourceLink {\n  id                   String   @id @default(uuid())\n  property_id          String\n  source_property_id   String\n  confidence_score     Decimal? @db.Decimal(5, 2)\n  is_primary_source    Boolean  @default(false)\n  last_normalized_hash String? // SourceProperty.content_hash as of the last AI normalization; lets us skip re-normalizing unchanged listings\n  created_at           DateTime @default(now())\n  updated_at           DateTime @updatedAt\n\n  property        Property       @relation(fields: [property_id], references: [id], onDelete: Cascade)\n  source_property SourceProperty @relation(fields: [source_property_id], references: [id], onDelete: Cascade)\n\n  @@unique([property_id, source_property_id])\n  @@index([property_id])\n  @@index([source_property_id])\n  @@map(\"property_source_links\")\n}\n\n// New: spec section 14 Property History -- append-only audit log of everything that happened to a\n// Property. This is what powers \"Price Changes\", \"Images Added/Removed\", \"Removal\",\n// \"Reappearance\" etc. in the property detail view. Never mutated, only appended to.\nmodel PropertyHistory {\n  id           String                   @id @default(uuid())\n  property_id  String\n  event_type   PropertyHistoryEventType\n  field        String? // e.g. \"price\", \"images\", \"status\" -- null for CREATED/REMOVED/REAPPEARED\n  old_value    Json?\n  new_value    Json?\n  crawl_run_id String? // which crawl detected this change, if any\n  created_at   DateTime                 @default(now())\n\n  property  Property  @relation(fields: [property_id], references: [id], onDelete: Cascade)\n  crawl_run CrawlRun? @relation(fields: [crawl_run_id], references: [id], onDelete: SetNull)\n\n  @@index([property_id])\n  @@index([event_type])\n  @@index([crawl_run_id])\n  @@map(\"property_history\")\n}\n\n/// User-owned, editable copy of a canonical Property. Created automatically the first time a\n/// tracked agency's scraper surfaces a matching Property; after that, edits apply ONLY to this\n/// row -- the canonical Property keeps being updated by the crawler independently.\n/// `is_modified` / `last_synced_at` track whether (and when) this copy has diverged, so the UI\n/// can show a \"this differs from the source listing\" banner and offer a manual re-sync.\nmodel UserProperty {\n  id                      String         @id @default(uuid())\n  user_id                 String\n  canonical_property_id   String\n  property_id             String\n  internal_id             String?\n  integration_property_id String?\n  title                   String\n  description             String?\n  listing_type            ListingType    @default(UNKNOWN)\n  property_type           PropertyType   @default(UNKNOWN)\n  status                  PropertyStatus @default(ACTIVE)\n  price                   Decimal?       @db.Decimal(14, 2)\n  currency                String?        @default(\"EUR\")\n  city                    String?\n  district                String?\n  address                 String?\n  postal_code             String?\n  country                 String?\n  latitude                Decimal?       @db.Decimal(10, 7)\n  longitude               Decimal?       @db.Decimal(10, 7)\n  square_meters           Decimal?       @db.Decimal(10, 2)\n  bedrooms                Int?\n  bathrooms               Int?\n  floor                   String?\n  construction_year       Int?\n  renovation_year         Int?\n  features                Json?\n  images                  Json?\n  normalized_data         Json?\n  estateweb_type_id       Int?\n  estateweb_location_id   Int?\n  estateweb_scope_id      Int?\n  cms_fields              Json?\n  cms_metadata            Json?\n  video_url               String?\n  distance_airport        String?\n  distance_port           String?\n  distance_beach          String?\n  price_start             Decimal?       @db.Decimal(14, 2)\n  price_web               Decimal?       @db.Decimal(14, 2)\n  duplicate_group_id      String?\n  is_modified             Boolean        @default(false)\n  pending_crm_update      Boolean        @default(false)\n  last_synced_at          DateTime? // last time this copy was refreshed from canonical_property\n  created_at              DateTime       @default(now())\n  updated_at              DateTime       @updatedAt\n\n  user                   User                       @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  canonical_property     Property                   @relation(fields: [canonical_property_id], references: [id], onDelete: Cascade)\n  integration_properties IntegrationProperty[]\n  localized_contents     PropertyLocalizedContent[]\n  cost_logs              CostLog[]\n\n  @@unique([user_id, canonical_property_id])\n  @@index([user_id])\n  @@index([canonical_property_id])\n  @@index([property_id])\n  @@map(\"user_properties\")\n}\n\nmodel ContentPublishingConfig {\n  id                     String   @id @default(uuid())\n  user_tracked_agency_id String   @unique\n  ai_titles_enabled      Boolean  @default(false)\n  use_ai_batch           Boolean  @default(false)\n  is_enabled             Boolean  @default(true)\n  notes                  String?\n  created_at             DateTime @default(now())\n  updated_at             DateTime @updatedAt\n\n  user_tracked_agency UserTrackedAgency @relation(fields: [user_tracked_agency_id], references: [id], onDelete: Cascade)\n  outputs             ContentOutput[]\n  ai_title_families   AiTitleFamily[]\n  ai_batch_runs       AiBatchRun[]\n\n  @@map(\"content_publishing_configs\")\n}\n\nmodel ContentOutput {\n  id                           String                        @id @default(uuid())\n  config_id                    String\n  language                     ContentLanguage\n  title_strategy               TitleProductionStrategy\n  description_strategy         DescriptionProductionStrategy\n  description_content_language ContentLanguage?\n  ai_title_family_id           String?\n  created_at                   DateTime                      @default(now())\n  updated_at                   DateTime                      @updatedAt\n\n  config          ContentPublishingConfig @relation(fields: [config_id], references: [id], onDelete: Cascade)\n  ai_title_family AiTitleFamily?          @relation(fields: [ai_title_family_id], references: [id], onDelete: Restrict)\n\n  @@unique([config_id, language])\n  @@index([ai_title_family_id])\n  @@map(\"content_outputs\")\n}\n\nmodel AiTitleFamily {\n  id                 String           @id @default(uuid())\n  config_id          String\n  name               String\n  model              String?\n  use_batch          Boolean?\n  instructions       String?\n  writing_language   ContentLanguage?\n  generation_options Json?\n  is_enabled         Boolean          @default(true)\n  created_at         DateTime         @default(now())\n  updated_at         DateTime         @updatedAt\n\n  config        ContentPublishingConfig @relation(fields: [config_id], references: [id], onDelete: Cascade)\n  outputs       ContentOutput[]\n  ai_batch_runs AiBatchRun[]\n\n  @@unique([config_id, name])\n  @@map(\"ai_title_families\")\n}\n\nmodel PropertyLocalizedContent {\n  id               String          @id @default(uuid())\n  user_property_id String\n  content_type     ContentType\n  language         ContentLanguage\n  production       String\n  text             String          @db.Text\n  is_stale         Boolean         @default(false)\n  created_at       DateTime        @default(now())\n  updated_at       DateTime        @updatedAt\n\n  user_property UserProperty @relation(fields: [user_property_id], references: [id], onDelete: Cascade)\n\n  @@unique([user_property_id, content_type, language])\n  @@index([user_property_id])\n  @@map(\"property_localized_contents\")\n}\n\nmodel AiBatchRun {\n  id                 String           @id @default(uuid())\n  kind               AiBatchRunKind   @default(TITLE_FAMILY)\n  status             AiBatchRunStatus @default(SUBMITTED)\n  openai_batch_id    String?          @unique\n  config_id          String?\n  ai_title_family_id String?\n  crawl_run_id       String?\n  user_property_ids  Json\n  metadata           Json?\n  error_message      String?\n  created_at         DateTime         @default(now())\n  updated_at         DateTime         @updatedAt\n\n  config          ContentPublishingConfig? @relation(fields: [config_id], references: [id], onDelete: SetNull)\n  ai_title_family AiTitleFamily?           @relation(fields: [ai_title_family_id], references: [id], onDelete: SetNull)\n  crawl_run       CrawlRun?                @relation(fields: [crawl_run_id], references: [id], onDelete: SetNull)\n  cost_logs       CostLog[]\n\n  @@index([status])\n  @@index([config_id])\n  @@index([crawl_run_id])\n  @@map(\"ai_batch_runs\")\n}\n\n/// Unified billable-operation ledger -- one row per cost-incurring call (AI normalization,\n/// AI title generation, Google Translate, Dewatermark image processing, ...). Sits alongside\n/// (not instead of) CrawlRun.ai_* columns, which stay as the crawl-runs page's own summary.\nmodel CostLog {\n  id                     String            @id @default(uuid())\n  user_id                String?\n  operation_type         CostOperationType\n  provider               IntegrationType\n  model                  String?\n  input_quantity         Int? // tokens (AI) or characters (translation)\n  output_quantity        Int? // output tokens (AI)\n  unit_count             Int? // e.g. images processed (dewatermark)\n  input_cost             Decimal?          @db.Decimal(12, 6)\n  output_cost            Decimal?          @db.Decimal(12, 6)\n  total_cost             Decimal           @db.Decimal(12, 6)\n  currency               String            @default(\"USD\")\n  crawl_run_id           String?\n  user_property_id       String?\n  user_tracked_agency_id String?\n  ai_batch_run_id        String?\n  metadata               Json?\n  created_at             DateTime          @default(now())\n\n  user                User?              @relation(fields: [user_id], references: [id], onDelete: SetNull)\n  crawl_run           CrawlRun?          @relation(fields: [crawl_run_id], references: [id], onDelete: SetNull)\n  user_property       UserProperty?      @relation(fields: [user_property_id], references: [id], onDelete: SetNull)\n  user_tracked_agency UserTrackedAgency? @relation(fields: [user_tracked_agency_id], references: [id], onDelete: SetNull)\n  ai_batch_run        AiBatchRun?        @relation(fields: [ai_batch_run_id], references: [id], onDelete: SetNull)\n\n  @@index([user_id])\n  @@index([operation_type])\n  @@index([provider])\n  @@index([created_at])\n  @@index([crawl_run_id])\n  @@map(\"cost_logs\")\n}\n\nmodel IntegrationProperty {\n  id                           String   @id @default(uuid())\n  user_id                      String\n  user_integration_settings_id String\n  user_property_id             String\n  images                       Json?\n  sites                        Json?\n  ads                          Json?\n  created_at                   DateTime @default(now())\n  updated_at                   DateTime @updatedAt\n\n  user                      User                    @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  user_integration_settings UserIntegrationSettings @relation(fields: [user_integration_settings_id], references: [id], onDelete: Cascade)\n  user_property             UserProperty            @relation(fields: [user_property_id], references: [id], onDelete: Cascade)\n\n  @@unique([user_id, user_integration_settings_id, user_property_id], map: \"integration_properties_user_settings_user_property_key\")\n  @@index([user_id])\n  @@index([user_property_id])\n  @@index([user_integration_settings_id])\n  @@map(\"integration_properties\")\n}\n\n/// Singleton table (single row, fixed id) holding tunable admin-editable parameters for the\n/// whole app, grouped by subsystem prefix (crawler_*, and more subsystems over time). Columns\n/// are nullable -- PlatformConfigService resolves nulls to in-code defaults per subsystem, so\n/// this table is never a hard requirement for anything to run.\nmodel PlatformConfig {\n  id                                           String   @id @default(\"singleton\")\n  crawler_max_pages                            Int?\n  crawler_page_timeout_ms                      Int?\n  crawler_selector_timeout_ms                  Int?\n  crawler_scroll_pause_ms                      Int?\n  crawler_detail_concurrency                   Int?\n  crawler_detail_delay_ms                      Int?\n  crawler_worker_concurrency                   Int?\n  crawler_job_timeout_ms                       Int?\n  crawler_chromium_max_contexts_before_restart Int?\n  normalization_ai_raw_description_max_chars   Int?\n  dewatermark_cost_per_image                   Decimal? @db.Decimal(12, 6)\n  created_at                                   DateTime @default(now())\n  updated_at                                   DateTime @updatedAt\n\n  @@map(\"platform_config\")\n}\n\n/// Generic uploaded file record (logos, banners, media, and computer-use screenshots).\nmodel Document {\n  id         String       @id @default(uuid())\n  user_uuid  String\n  filename   String\n  mimetype   String\n  size       Int\n  url        String\n  path       String\n  type       DocumentType @default(LOGO)\n  created_at DateTime     @default(now())\n\n  computer_use_steps_before ComputerUseStep[] @relation(\"ComputerUseStepScreenshotBefore\")\n  computer_use_steps_after  ComputerUseStep[] @relation(\"ComputerUseStepScreenshotAfter\")\n\n  @@index([user_uuid])\n  @@map(\"documents\")\n}\n"
}

